 -L/usr/lib/gcc/x86_64-linux-gnu/9/../../..
 /tmp/cclu3MJY.o -lgcc --push-state --as-needed -lgcc_s
 --pop-state -lc -lgcc --push-state --as-needed -lgcc_s
 --pop-state /usr/lib/gcc/x86_64-linux-gnu/9/crtendS.o
